namespace sv_fc46612a80cf4077bdfde6e03e58e256.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

namespace sv_fc46612a80cf4077bdfde6e03e58e256.Models;

/// <summary>
/// Mutable form models used during the multi-step wizard, converted to records on submission.
/// </summary>
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";
}

public record WorkEntryModel
{
    public string Company { get; init; } = "";
    public string Title { get; init; } = "";
    public DateTime StartDate { get; init; } = DateTime.Today;
    public DateTime? EndDate { get; init; }
    public bool IsCurrent { get; init; }
    public string Description { get; init; } = "";
}

public record ReferenceModel
{
    public string Name { get; init; } = "";
    public string Relationship { get; init; } = "";
    public string Email { get; init; } = "";
    public string Phone { get; init; } = "";
}

@page "/apply"
@rendermode InteractiveServer
@using sv_fc46612a80cf4077bdfde6e03e58e256.Models
@namespace sv_fc46612a80cf4077bdfde6e03e58e256.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep" CompletedUpTo="@_completedUpTo" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@_personalInfo" OnNext="NextStep" ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@_workEntries" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="@_references" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep @bind-CoverLetter="_coverLetter" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep
                Personal="@_personalInfo"
                WorkEntries="@_workEntries"
                References="@_references"
                CoverLetter="@_coverLetter"
                OnBack="PreviousStep"
                OnEditStep="GoToStep"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private int _completedUpTo;

    private PersonalInfoModel _personalInfo = new();
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
    private string _coverLetter = "";

    private void NextStep()
    {
        _currentStep++;
        if (_currentStep > _completedUpTo)
            _completedUpTo = _currentStep;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step <= _completedUpTo)
            _currentStep = step;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
            new WorkHistory(_workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
            _references.Where(r => !string.IsNullOrWhiteSpace(r.Name)).Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

