+.form-group input[type="text"],
+.form-group input[type="email"],
+.form-group input[type="tel"],
+.form-group input[type="date"],
+.form-group textarea {
+    width: 100%;
+    padding: 0.6rem 0.8rem;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    transition: border-color 0.2s;
+    box-sizing: border-box;
+}
+
+.form-group input:focus,
+.form-group textarea:focus {
+    outline: none;
+    border-color: #4361ee;
+    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.15);
+}
+
+.form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+/* Fieldsets */
+fieldset {
+    border: 1px solid #e8e8e8;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+fieldset legend {
+    font-weight: 600;
+    color: #555;
+    padding: 0 0.5rem;
+}
+
+/* Buttons */
+.step-actions {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-primary {
+    background: #4361ee;
+    color: #fff;
+    border: none;
+    padding: 0.7rem 1.8rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #3651d4;
+}
+
+.btn-primary:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-outline {
+    background: transparent;
+    color: #4361ee;
+    border: 1px solid #4361ee;
+    padding: 0.7rem 1.8rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-outline:hover {
+    background: #f0f3ff;
+}
+
+.btn-secondary {
+    background: #f0f3ff;
+    color: #4361ee;
+    border: 1px solid #d0d9ff;
+    padding: 0.5rem 1.2rem;
+    border-radius: 4px;
+    font-size: 0.85rem;
+    cursor: pointer;
+    margin-bottom: 1rem;
+}
+
+.btn-secondary:hover {
+    background: #e0e7ff;
+}
+
+.btn-danger {
+    background: #fee;
+    color: #d32f2f;
+    border: 1px solid #fcc;
+    padding: 0.4rem 1rem;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    margin-top: 0.5rem;
+}
+
+.btn-danger:hover {
+    background: #fdd;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #4361ee;
+    cursor: pointer;
+    font-size: 0.85rem;
+    text-decoration: underline;
+    padding: 0;
+}
+
+.btn-submit {
+    padding: 0.8rem 2.5rem;
+    font-size: 1rem;
+}
+
+/* Character count */
+.char-count {
+    display: block;
+    text-align: right;
+    font-size: 0.8rem;
+    color: #888;
+    margin-top: 0.3rem;
+}
+
+/* Error messages */
+.error-message {
+    background: #fff3f3;
+    border: 1px solid #fcc;
+    color: #c62828;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-bottom: 1rem;
+    font-size: 0.9rem;
+}
+
+/* Review section */
+.review-section {
+    border: 1px solid #e8e8e8;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #333;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.3rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #666;
+    font-size: 0.85rem;
+}
+
+.review-section dd {
+    margin: 0;
+    font-size: 0.9rem;
+}
+
+.review-item {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.review-item:last-child {
+    border-bottom: none;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f9f9f9;
+    padding: 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    max-height: 200px;
+    overflow-y: auto;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.confirmation h3 {
+    color: #2ec4b6;
+    font-size: 1.5rem;
+}
+
+.confirmation p {
+    color: #555;
+    font-size: 1rem;
+}
+
+/* Responsive */
+@media (max-width: 600px) {
+    .form-row {
+        grid-template-columns: 1fr;
+    }
+
+    .step-indicator ol {
+        flex-wrap: wrap;
+        gap: 0.5rem;
+    }
+
+    .step-indicator .step-label {
+        font-size: 0.65rem;
+    }
+}
+

